const gap = Math.min(4, Math.max(1, Math.round(med(gaps) || 2)));
const cnt = {}, hit = {};
let ls = null;
for (const h of hist) { if (ls) { const k = diff(ls, h.d); cnt[k] = (cnt[k] || 0) + 1; if (Number(h.s) === 1) hit[k] = (hit[k] || 0) + 1; } if (Number(h.s) === 1) ls = h.d; }
const pk = (k) => { const prior = k % gap === 0 ? 0.85 : (k > gap ? 0.6 : 0.1); return ((hit[k] || 0) + 2 * prior) / ((cnt[k] || 0) + 2); };

const starts = hist.filter((h) => Number(h.s) === 1 && toMin(h.st) !== null).map((h) => toMin(h.st)).slice(-8);
let win = null;
if (starts.length) {
  const sm = med(starts), lo = Math.min(...starts), hi = Math.max(...starts);
  let a, b;
  if (starts.length >= 3) { a = Math.max(lo, sm - 45); b = Math.min(hi, sm + 45); if (b - a < 30) { a = sm - 15; b = sm + 45; } } else { a = sm - 30; b = sm + 60; }
  win = h12(a) + ' - ' + h12(b);
}

const lastActual = supplyDays[supplyDays.length - 1];
let anchor = lastActual;
const days = [];
for (let i = 0; i < 7; i++) {
  const d = addDays(today, i);
  const k = diff(anchor, d);
  let status, p;
  if (i === 0 && todaySupply) { status = 'came'; p = 100; }
  else {
    p = k <= 0 ? 0 : Math.round(pk(k) * 100);
    if (i === 0 && minNow >= 18 * 60) status = 'none';
    else status = p >= 50 ? 'expected' : 'unlikely';
    if (status === 'expected') anchor = d;
  }
  days.push({ date: d, label: label(d), k, p, status });
}
const rel = (d) => (d === today ? ' (today)' : d === addDays(today, 1) ? ' (tomorrow)' : '');
const next = days.find((x) => x.status === 'expected') || null;
const nextText = next ? 'Next supply: ' + next.label + rel(next.date) + (win ? ', around ' + win : '') + ' (' + next.p + '%).' : 'Next supply: not clear from the history yet.';
const line = (x) => x.label + ': ' + (x.status === 'came' ? 'supply came' + (firstAt ? ' at ' + t12(firstAt) : '')
  : x.status === 'expected' ? 'supply expected (' + x.p + '%)' + (win ? ', ' + win : '')
  : x.status === 'none' ? 'no supply today' : 'no supply expected (' + x.p + '%)');
global.set('waterWeek', { at: now, today, gap, lastSupply: lastActual, samples: hist.length, window: win, next, days, nextText, weekText: days.map(line).join('\n') });
const d0 = days[0];
global.set('supplyExpect', { date: today, expected: (d0.status === 'came' || d0.status === 'expected') ? 'supply' : 'none', gap, lastSupply: lastActual, nextSupply: next ? next.date : null, regular: true, basis: 'code week forecast: today ' + d0.status + ' (' + d0.p + '%)', at: now });
node.status({ fill: 'green', shape: 'dot', text: 'today ' + d0.status + ' | ' + nextText.slice(0, 50) });
return null;
